// Band centres and widths from an ENVI header, in micrometres. Without "wavelength units", the
// header is in nanometres when any centre is above 100, and the widths take the centres' unit.
export function bandsOf(header) {
  const unit = header['wavelength units']?.toLowerCase();
  const nanometres = unit === 'nanometers' || (unit !== 'micrometers' && header.wavelength.some((v) => v > 100));
  const scale = nanometres ? 1 / 1000 : 1;
  return { centres: header.wavelength.map((v) => v * scale), fwhm: header.fwhm?.map((v) => v * scale) };
}

