import { test } from 'node:test';
import assert from 'node:assert/strict';
import { bandsOf } from '../src/envi-bands.js';

const close = (a, b) => assert.ok(Math.abs(a - b) < 1e-9, a + ' is not ' + b);

test('without units, narrow widths take the nanometre unit of the centres', () => {
  const bands = bandsOf({ wavelength: [366, 2496], fwhm: [9.85, 9.6] });
  close(bands.centres[0], 0.366);
  close(bands.fwhm[0], 0.00985);
});

test('without units, micrometre centres keep their widths', () => {
  const bands = bandsOf({ wavelength: [0.45, 2.2], fwhm: [0.01, 0.02] });
  assert.deepEqual(bands.fwhm, [0.01, 0.02]);
});

test('stated units are used as given', () => {
  const nm = bandsOf({ 'wavelength units': 'Nanometers', wavelength: [500], fwhm: [10] });
  close(nm.centres[0], 0.5);
  close(nm.fwhm[0], 0.01);
  const um = bandsOf({ 'wavelength units': 'Micrometers', wavelength: [0.5], fwhm: [0.01] });
  assert.deepEqual(um, { centres: [0.5], fwhm: [0.01] });
});
